import{_ as s,o as a,c as i,ag as n}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"SetJointDyn 设置关节动态特性","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetJointDyn.md","filePath":"3. 指令/5. 设置指令/SetJointDyn.md","lastUpdated":1778862643000}'),e={name:"3. 指令/5. 设置指令/SetJointDyn.md"};function r(h,t,o,d,l,p){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="setjointdyn-设置关节动态特性" tabindex="-1">SetJointDyn 设置关节动态特性 <a class="header-anchor" href="#setjointdyn-设置关节动态特性" aria-label="Permalink to &quot;SetJointDyn 设置关节动态特性&quot;">​</a></h1><p>该指令用于<strong>全局设置机器人关节空间的动态特性参数</strong>。执行后，系统会修改关节运动的&quot;软硬&quot;程度。这在需要保护减速机寿命、搬运易碎品（需平滑启动）或提高循环效率（需高加速度）时非常重要。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetJointDyn(Acc, Dec, Jerk, Torq) SetJointDyn(加速度, 减速度, 加加速度, 力矩)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Acc：加速度 (%)</td><td>int / INT 变量</td><td>设置关节从静止达到最高速度的快慢。数值越大，启动越快。</td><td>取值范围：<strong>1-100</strong>。</td></tr><tr><td>Dec：减速度 (%)</td><td>int / INT 变量</td><td>设置关节从运动状态停止下来的快慢。数值越大，刹车越急。</td><td>取值范围：<strong>1-100</strong>。</td></tr><tr><td>Jerk：加加速度 (%)</td><td>int / INT 变量</td><td>决定了加速度的变化率，即运动的&quot;平滑度&quot;。数值越小，运行越柔和，振动越小。</td><td>取值范围：<strong>1-100</strong>。</td></tr><tr><td>Torq：力矩 (%)</td><td>int / INT 变量</td><td>限制关节电机的输出扭矩。在碰撞检测或轻量化搬运时可调低此值。</td><td>取值范围：<strong>1-100</strong>。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p><code>SetJointDyn</code> 是一种<strong>状态设定指令</strong>。它本身不产生动作，但会像&quot;滤镜&quot;一样作用于后续所有的关节运动指令（如 <code>MovJ</code>）。如果不重新设置，这些参数将一直生效。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetJointDyn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人向 <strong>P1</strong> 点运动时，将以 <strong>80%</strong> 的加速度、减速度和冲击率运行，同时限制电机输出力矩为额定的 <strong>60%</strong>。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>轻载加速</strong>：当末端负载很轻时，调高 Acc 和 Dec 以缩短循环周期。</li><li><strong>减振保护</strong>：在搬运精密电子元器件时，调低 Jerk 以消除运动启动和停止时的抖动。</li><li><strong>安全性限制</strong>：在调试阶段调低 Torq，当发生意外碰撞时，电机能更早触发报警保护硬件。</li></ul>`,18)])])}const c=s(e,[["render",r]]);export{g as __pageData,c as default};
